501	  // 中文、表情按 UTF-8 编码后的字节数计入；这与字段按 Unicode 码点的上限是两回事。
502	  const declaredLength = Number(req.headers['content-length']);
503	  let tooLarge = Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES;
504	  const chunks: Buffer[] = [];
505	  let size = 0;
506	  // 超限后不能写出 400 就立即 req.destroy()：客户端可能还在发送，强断会让它只看到
507	  // 连接断开，读不到完整错误。这里继续把请求体读完（排空，天然带背压），
508	  // 等请求正常结束后再回复，客户端只要发完并保持连接等待，就能收到完整可解析的 400。
509	  // 超限后的字节不再缓存：绝不能拿已收到的前缀去解析，更不能截断后尝试保存。
510	  try {
511	    for await (const chunk of req as AsyncIterable<Buffer>) {
512	      size += chunk.length;
513	      if (tooLarge) continue;
514	      if (size > MAX_BODY_BYTES) {
515	        tooLarge = true;
516	        chunks.length = 0;
517	        continue;
518	      }
519	      chunks.push(chunk);
520	    }
521	  } catch {
522	    // 客户端中途断开或请求流出错：响应已无处可写，安静结束，不能变成 500。
