538	  const rawBody = Buffer.concat(chunks);
539	  let bodyText: string;
540	  try {
541	    bodyText = UTF8_DECODER.decode(rawBody);
542	  } catch {
543	    respond(res, 400, { error: '请求体不是有效的 UTF-8' });
544	    return;
545	  }
546	  let payload: unknown;
547	  try {
548	    payload = JSON.parse(bodyText);
549	  } catch {
550	    respond(res, 400, { error: '请求体不是有效的 JSON' });
551	    return;
552	  }
553	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
554	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
555	    return;
556	  }
557	  const body = payload as Record<string, unknown>;
558	  for (const field of ['title', 'description'] as const) {
559	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
560	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
