584	  try {
585	    records = readIdeas();
586	  } catch {
587	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
588	    return;
589	  }
590	  records.unshift(idea);
591	  try {
592	    saveIdeas(records);
593	  } catch {
594	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
595	    return;
596	  }
597	  respond(res, 201, { idea });
598	}
599	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
