    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
    case 'description-empty': return '详细说明不能为空。';
    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
