30	interface El {
31	  tagName: string;
32	  className: string;
33	  hidden: boolean;
34	  value: string;
35	  href: string;
36	  dateTime: string;
37	  children: El[];
38	  text: string | null;
39	  textContent: string;
40	  // 警戒标记：页面一旦通过 innerHTML 渲染内容即为 true（纯文本展示不允许走 innerHTML）
41	  innerHTMLAssigned: boolean;
42	  listeners: Record<string, Array<(event: unknown) => unknown>>;
43	  append(...nodes: El[]): void;
44	  replaceChildren(...nodes: El[]): void;
45	  addEventListener(type: string, fn: (event: unknown) => unknown): void;
46	  reset(): void;
47	}
48	
49	function makeElement(tag: string): El {
50	  const node = {
51	    tagName: tag.toUpperCase(),
52	    className: '',
53	    hidden: false,
54	    value: '',
55	    href: '',
56	    dateTime: '',
57	    children: [],
58	    text: null as string | null,
59	    innerHTMLAssigned: false,
60	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
61	    append(...nodes: El[]): void {
62	      this.children.push(...nodes);
63	    },
64	    replaceChildren(...nodes: El[]): void {
65	      this.children = [...nodes];
66	    },
67	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
68	      (this.listeners[type] ??= []).push(fn);
69	    },
70	    reset(): void {},
71	  };
72	  Object.defineProperty(node, 'textContent', {
73	    get(this: any): string {
74	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
75	    },
76	    set(this: any, value: unknown): void {
77	      this.text = String(value);
78	    },
79	  });
80	  // innerHTML 只记录不解析：意见内容若改走 innerHTML 渲染，textContent 断言会失败，
81	  // innerHTMLAssigned 标记则给出更直接的原因
82	  Object.defineProperty(node, 'innerHTML', {
83	    get(): string {
84	      return '';
85	    },
86	    set(this: any, value: unknown): void {
87	      this.innerHTMLAssigned = true;
88	    },
89	  });
90	  return node as El;
91	}
92	
93	interface Gate {
94	  promise: Promise<unknown>;
95	  resolve: (value: unknown) => void;
96	  reject: (error: Error) => void;
97	}
98	
99	function gate(): Gate {
100	  let resolve!: (value: unknown) => void;
101	  let reject!: (error: Error) => void;
102	  const promise = new Promise<unknown>((res, rej) => {
103	    resolve = res;
104	    reject = rej;
105	  });
106	  return { promise, resolve, reject };
107	}
108	
109	function jsonResponse(status: number, body: unknown): any {
110	  return {
111	    ok: status >= 200 && status < 300,
112	    status,
113	    json: async () => body,
114	  };
115	}
116	
117	function brokenJsonResponse(status = 201): any {
118	  return {
119	    ok: status >= 200 && status < 300,
120	    status,
121	    json: async () => {
122	      throw new SyntaxError('响应体不是有效 JSON');
123	    },
124	  };
125	}
126	
127	const flush = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));
128	
129	let ideaSeq = 0;
130	function makeIdea(partial: Record<string, unknown> = {}): Record<string, unknown> {
131	  ideaSeq += 1;
132	  return {
133	    id: `id-${ideaSeq}`,
134	    title: `标题 ${ideaSeq}`,
135	    description: `详细说明 ${ideaSeq}`,
136	    scenario: '',
137	    createdAt: '2026-01-01T00:00:00.000Z',
138	    ...partial,
139	  };
140	}
141	
142	const SUCCESS_TEXT = '提交成功，你的意见已保存。';
143	const EMPTY_TEXT = '还没有意见记录。';
144	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
145	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
146	const NETWORK_ERROR_TEXT = '网络错误，提交未成功，请重试。';
147	const SUBMIT_FAILED_TEXT = '提交失败，请稍后重试。';
148	
149	class Harness {
150	  els: Record<string, El> = {};
151	  // 页面脚本通过 document.createElement 创建过的全部元素（按创建先后），
152	  // 用于断言渲染只产生纯文本结构，不为意见内容创建脚本、图片、链接、表单等元素
153	  created: El[] = [];
154	  gets: Gate[] = [];
155	  getsIssued = 0;
156	  posts: Gate[] = [];
157	  postsIssued = 0;
158	  postBodies: unknown[] = [];
159	
160	  constructor(script: string) {
161	    const byId: Map<string, El> = new Map();
162	    const register = (id: string, tag: string, hidden = false): El => {
163	      const node = makeElement(tag);
164	      node.hidden = hidden;
165	      byId.set(id, node);
166	      this.els[id] = node;
167	      return node;
168	    };
169	    const form = register('idea-form', 'form');
170	    const titleInput = register('f-title', 'input');
171	    const descInput = register('f-desc', 'textarea');
172	    const scenarioInput = register('f-scenario', 'textarea');
173	    register('search-form', 'form');
174	    register('f-search', 'input');
175	    register('search-clear', 'button');
176	    register('error', 'p', true);
177	    register('success', 'p', true);
178	    register('empty', 'p', true);
179	    register('ideas', 'div');
180	    form.reset = (): void => {
181	      titleInput.value = '';
182	      descInput.value = '';
183	      scenarioInput.value = '';
184	    };
185	    const documentMock = {
186	      getElementById: (id: string): El => byId.get(id)!,
187	      createElement: (tag: string): El => {
188	        const el = makeElement(tag);
189	        this.created.push(el);
190	        return el;
191	      },
192	    };
193	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
194	      const method = init?.method ?? 'GET';
195	      const pending = gate();
196	      if (method === 'POST') {
197	        this.posts.push(pending);
198	        this.postsIssued += 1;
199	        this.postBodies.push(init?.body);
200	      } else {
201	        this.gets.push(pending);
202	        this.getsIssued += 1;
203	      }
204	      return pending.promise;
205	    };
206	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
207	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
208	  }
209	
210	  setForm(values: { title?: string; description?: string; scenario?: string }): void {
211	    if (values.title !== undefined) this.els['f-title'].value = values.title;
212	    if (values.description !== undefined) this.els['f-desc'].value = values.description;
213	    if (values.scenario !== undefined) this.els['f-scenario'].value = values.scenario;
214	  }
215	
216	  // 模拟真实用户输入：赋值并触发 input 事件（setForm 不触发事件，只用于布置初始状态）
217	  edit(id: string, value: string): void {
218	    const el = this.els[id];
219	    el.value = value;
220	    for (const fn of el.listeners.input ?? []) fn({ target: el });
221	  }
222	
223	  // 触发表单 submit 监听器，返回监听器（async 函数）的 Promise
224	  submit(): Promise<unknown> {
225	    const handler = this.els['idea-form'].listeners.submit[0];
226	    return handler({ preventDefault(): void {} });
227	  }
228	
229	  // 在搜索框布置文字（不触发事件）并点击“搜索”，返回监听器的返回值
230	  search(keyword: string): unknown {
231	    this.els['f-search'].value = keyword;
232	    const handler = this.els['search-form'].listeners.submit[0];
233	    return handler({ preventDefault(): void {} });
234	  }
235	
236	  // 点击“清空”按钮
237	  clearSearch(): void {
238	    this.els['search-clear'].listeners.click[0]({});
239	  }
240	
241	  articles(): El[] {
242	    return this.els.ideas.children.filter((node) => node.tagName === 'ARTICLE');
243	  }
244	
245	  titles(): string[] {
246	    return this.articles().map((article) => article.children.find((n) => n.tagName === 'H3')!.textContent);
247	  }
248	}
249	
250	function findScenario(article: El): El | undefined {
251	  return article.children.find(
252	    (node) =>
253	      node.tagName === 'P' &&
254	      node.children.some((child) => child.tagName === 'STRONG' && child.textContent === '使用场景：'),
255	  );
256	}
257	
258	function findViewLink(article: El): El | undefined {
259	  return article.children.find((node) => node.tagName === 'A' && node.className === 'view-link');
260	}
261	
262	// 首页为某条意见生成的独立查看地址：标识恰为“.”或“..”时改走查询串
263	// （路径段会被网址路径归一化移除），其余标识走路径段；两者都经 encodeURIComponent。
264	function expectedViewHref(id: string): string {
265	  return id === '.' || id === '..'
266	    ? `/ideas?id=${encodeURIComponent(id)}`
267	    : `/ideas/${encodeURIComponent(id)}`;
268	}
269	
270	// 校验一条已渲染的意见与原记录逐字段对应：标题、详细说明、非空使用场景、提交时间、
271	// 独立查看入口（链接只由该记录的 id 决定，与标题/说明文字无关）
272	function assertArticleMatches(article: El, idea: Record<string, unknown>): void {
273	  const heading = article.children.find((n) => n.tagName === 'H3')!;
274	  assert.equal(heading.textContent, idea.title);
275	  const description = article.children.find((n) => n.tagName === 'P' && n.children.length === 0)!;
276	  assert.equal(description.textContent, idea.description);
277	  const scenarioNode = findScenario(article);
278	  const expectsScenario =
279	    typeof idea.scenario === 'string' && idea.scenario.trim().length > 0;
280	  assert.equal(
281	    Boolean(scenarioNode),
282	    expectsScenario,
283	    `使用场景展示与否应与记录一致：${String(idea.scenario)}`,
284	  );
285	  if (expectsScenario) {
286	    const span = scenarioNode!.children.find((n) => n.tagName === 'SPAN')!;
287	    assert.equal(span.textContent, idea.scenario);
288	  }
289	  const time = article.children.find((n) => n.tagName === 'TIME')!;
290	  assert.equal(time.dateTime, idea.createdAt);
291	  // 每条意见都有独立查看入口：href 只由 id 经 encodeURIComponent 拼成，可直接分享
292	  const viewLink = findViewLink(article);
293	  assert.ok(viewLink, '每条意见都应有查看入口');
294	  assert.equal(viewLink!.href, expectedViewHref(String(idea.id)));
295	  assert.equal(viewLink!.textContent, '查看这条意见');
296	}
