  // 沿用接口原有顺序，不重排；每条只出现一次
  assert.deepEqual(h.titles(), ['支持 Apple 深色模式', '普通标题', '普通标题']);
  // 命中记录的全部字段仍按原文渲染，字段对应关系不变
  assertArticleMatches(h.articles()[1], inDesc);
  assertArticleMatches(h.articles()[2], inScenario);
});

