  h.gets[0].resolve(jsonResponse(200, { ideas }));
  await flush();

  // 一边填写意见草稿一边搜索：草稿原样保留，搜索词也保留
  h.edit('f-title', '正在写的标题');
  h.edit('f-desc', '正在写的说明\n第二行');
  h.edit('f-scenario', '正在写的场景');
  h.search('导出');
