// 解码再归一化），请求到不了这里。这两个标识由首页以 /ideas?id=<encoded> 的查询串形式
// 给出，查询串不做路径归一化；encodedId 无论是路径段还是查询值，都统一在这里解码。
//
// 兼容编码 %75XXXX（见 encodeCompatViewId）只用于含孤立代理码元、无法普通百分号编码的
// 历史标识。下面逐段切出兼容转义还原成代理码元，其余部分仍走标准 decodeURIComponent：
// 触发条件限定为编码端实际产出的形态（%75 + 四位大写十六进制、值在代理区 D800–DFFF），
// 因此普通百分号编码（包括把字母 u 编成 %75 的 %75ud800 之类）仍按原语义解码，
// 不会被误判；任何畸形百分号编码或无法还原的形态返回 null，按意见不存在处理，不猜测目标。
const COMPAT_ID_MARKER = /%75D[89A-F][0-9A-F]{2}/;
function decodeViewId(encoded: string): string | null {
  let decoded = '';
  let rest = encoded;
  for (;;) {
    const match = COMPAT_ID_MARKER.exec(rest);
    if (!match) break;
    const before = rest.slice(0, match.index);
    try {
      decoded += decodeURIComponent(before);
    } catch {
      // 兼容转义之外的普通部分含畸形百分号编码：整条标识无法可靠还原
      return null;
    }
    decoded += String.fromCharCode(parseInt(match[0].slice('%75'.length), 16));
    rest = rest.slice(match.index + match[0].length);
  }
  try {
    decoded += decodeURIComponent(rest);
  } catch {
    return null;
  }
  return decoded;
}
function showIdeaView(res: ServerResponse, encodedId: string): void {
  const targetId = decodeViewId(encodedId);
  if (targetId === null) {
    respond(res, 404, renderMessagePage('该意见不存在', '你查看的意见不存在，可能已被删除。'), { html: true });
    return;
