    // 孤立代理码元无法以合法 UTF-8 写进响应（统一落成替代符号 U+FFFD，未配对的高代理
    // 与低代理在页面上将无从区分）。先把每个孤立码元改写成字面的“反斜杠 uXXXX”文本：
    // 这六个字符全是普通 ASCII，不产生页面元素，也让仅差在孤立代理项的两条记录在页面上
    // 逐字可辨（\uD800 与 \uDC00 不同）。成对代理码元（完整表情）原样保留，不受影响。
    .replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g,
      (unit) => `\\u${unit.charCodeAt(0).toString(16).toUpperCase().padStart(4, '0')}`)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll(''"', '&quot;')
    .replaceAll("'", '&#39;');
}
type CompleteIdea = {
  id: string;
  title: string;
  description: string;
  scenario: string;
  createdAt: string;
};
function renderIdeaViewPage(idea: CompleteIdea): string {
  const scenarioBlock = idea.scenario.trim().length > 0
    ? `<p><strong>${VIEW_FIELD_LABELS.scenario}：</strong><span class="pre">${escapeHtml(idea.scenario)}</span></p>\n`

