  const dir = freshDir();
  const highId = `中${HIGH_UNIT}`;
  seedIdeas(dir, [
    { id: highId, title: '存在的高代理意见', description: '正文', scenario: '', createdAt: '2020-08-08T00:00:00.000Z' },
