  try {
    // 兼容转义后接畸形百分号编码：整条无法可靠还原，按不存在处理（不猜测、不 500）
    for (const segment of ['x%75D800%zz', '%75D800%E4%B8%AD', '%75DBFF', '%75D7FF']) {
      const res = await fetchViewRaw(server, segment);
      assert.equal(res.status, 404, segment);
